58	+public class AppDbContextFactory : IDesignTimeDbContextFactory<AppDbContext>
59	+{
60	+    public AppDbContext CreateDbContext(string[] args)
61	+    {
62	+        var connectionString = Environment.GetEnvironmentVariable("ConnectionStrings__Default")
63	+            ?? "Server=localhost;Database=seed-b-backend-design;Trusted_Connection=True;TrustServerCertificate=True;";
64	+
65	+        var optionsBuilder = new DbContextOptionsBuilder<AppDbContext>();
66	+        optionsBuilder.UseSqlServer(connectionString);
67	+
68	+        return new AppDbContext(optionsBuilder.Options);
69	+    }
70	+}
