7	+using Microsoft.EntityFrameworkCore;
8	+using seed_b_backend.Api.Data.Entities;
9	+
10	+namespace seed_b_backend.Api.Data;
11	+
12	+public class AppDbContext(DbContextOptions<AppDbContext> options) : DbContext(options)
13	+{
14	+    public DbSet<Category> Categories => Set<Category>();
15	+    public DbSet<Subcategory> Subcategories => Set<Subcategory>();
16	+    public DbSet<Supplier> Suppliers => Set<Supplier>();
17	+    public DbSet<Product> Products => Set<Product>();
18	+    public DbSet<Offer> Offers => Set<Offer>();
19	+
20	+    protected override void OnModelCreating(ModelBuilder modelBuilder)
21	+    {
22	+        modelBuilder.Entity<Category>()
23	+            .HasMany(c => c.Subcategories)
24	+            .WithOne(s => s.Category)
25	+            .HasForeignKey(s => s.CategoryId);
26	+
27	+        modelBuilder.Entity<Subcategory>()
28	+            .HasMany(s => s.Products)
29	+            .WithOne(p => p.Subcategory)
30	+            .HasForeignKey(p => p.SubcategoryId);
31	+
32	+        modelBuilder.Entity<Offer>(o =>
33	+        {
34	+            o.HasKey(x => new { x.ProductId, x.SupplierId });
35	+            o.Property(x => x.Price).HasColumnType("decimal(18,2)");
36	+
37	+            o.HasOne(x => x.Product)
38	+                .WithMany(p => p.Offers)
39	+                .HasForeignKey(x => x.ProductId);
40	+
41	+            o.HasOne(x => x.Supplier)
42	+                .WithMany(s => s.Offers)
43	+                .HasForeignKey(x => x.SupplierId);
44	+        });
45	+    }
46	+}
