698	+using System.Text.Json;
699	+using Microsoft.EntityFrameworkCore;
700	+using seed_b_backend.Api.Data.Entities;
701	+
702	+namespace seed_b_backend.Api.Data.Seeding;
703	+
704	+public static class DatabaseInitializer
705	+{
706	+    private static readonly JsonSerializerOptions SerializerOptions = new()
707	+    {
708	+        PropertyNameCaseInsensitive = true
709	+    };
710	+
711	+    public static async Task MigrateAsync(AppDbContext db)
712	+    {
713	+        await db.Database.MigrateAsync();
714	+    }
715	+
716	+    public static async Task SeedIfEmptyAsync(AppDbContext db, string seedFilePath)
717	+    {
718	+        if (await db.Products.AnyAsync())
719	+        {
720	+            return;
721	+        }
722	+
723	+        await using var stream = File.OpenRead(seedFilePath);
724	+        var seed = await JsonSerializer.DeserializeAsync<SeedRoot>(stream, SerializerOptions)
725	+            ?? throw new InvalidOperationException($"Anfangsdatenbestand konnte nicht aus '{seedFilePath}' gelesen werden.");
726	+
727	+        foreach (var kategorie in seed.Kategorien)
728	+        {
729	+            db.Categories.Add(new Category { Id = kategorie.Id, Name = kategorie.Name });
730	+
731	+            foreach (var unterkategorie in kategorie.Unterkategorien)
732	+            {
733	+                db.Subcategories.Add(new Subcategory
734	+                {
735	+                    Id = unterkategorie.Id,
736	+                    Name = unterkategorie.Name,
737	+                    CategoryId = kategorie.Id,
738	+                    AttributeNames = unterkategorie.Eigenschaften
739	+                });
740	+            }
741	+        }
742	+
743	+        foreach (var lieferant in seed.Lieferanten)
744	+        {
745	+            db.Suppliers.Add(new Supplier { Id = lieferant.Id, Name = lieferant.Name });
746	+        }
747	+
748	+        foreach (var produkt in seed.Produkte)
749	+        {
750	+            db.Products.Add(new Product
751	+            {
752	+                Id = produkt.Id,
753	+                Name = produkt.Name,
754	+                Description = produkt.Beschreibung,
755	+                SubcategoryId = produkt.UnterkategorieId,
756	+                Attributes = produkt.Eigenschaften.GetRawText(),
757	+                ViewCount = 0
758	+            });
759	+
760	+            foreach (var angebot in produkt.Angebote)
761	+            {
762	+                db.Offers.Add(new Offer
763	+                {
764	+                    ProductId = produkt.Id,
765	+                    SupplierId = angebot.LieferantId,
766	+                    Price = angebot.Preis
767	+                });
768	+            }
769	+        }
770	+
771	+        await db.SaveChangesAsync();
772	+    }
773	+
774	+    private sealed record SeedRoot(
775	+        List<SeedKategorie> Kategorien,
776	+        List<SeedLieferant> Lieferanten,
777	+        List<SeedProdukt> Produkte);
778	+
779	+    private sealed record SeedKategorie(string Id, string Name, List<SeedUnterkategorie> Unterkategorien);
780	+
781	+    private sealed record SeedUnterkategorie(string Id, string Name, List<string> Eigenschaften);
782	+
